<template><view class="wrap ui-page"><view class="head"><text class="eyebrow">TODAY'S BUSINESS</text><view class="head-row"><view class="name">{{ merchant || '商家工作台' }}</view><view class="status"><text class="dot"></text>营业中</view></view></view><view class="stats ui-card"><view><text class="num">{{ todayOrders }}</text><text>今日订单</text></view><view class="divider"></view><view><text class="num">¥{{ revenue }}</text><text>今日营收</text></view></view><view class="section-title">快捷操作</view><view class="actions"><view class="action ui-card" @tap="scan"><text class="icon">⌾</text><text>扫码核销</text><text class="note">快速验券</text></view><view class="action ui-card" @tap="records"><text class="icon">▤</text><text>核销记录</text><text class="note">查看明细</text></view></view></view></template>
<script setup lang="ts">import {ref} from 'vue';import {apiRequest} from '@mall/uni-shared';const merchant=ref(''),todayOrders=ref(0),revenue=ref('0.00');Promise.all([apiRequest<any>({url:'/api/mp/me/profile'}),apiRequest<any>({url:'/api/mp/workbench/kpi'})]).then(([me,kpi])=>{merchant.value=me?.tenant?.name||me?.tenantName||me?.user?.name||'商家';todayOrders.value=kpi?.todayOrders?.value??0;revenue.value=kpi?.todaySales?.value??'0.00'}).catch((e:any)=>uni.showToast({title:e.message||'工作台加载失败',icon:'none'}));function scan(){uni.switchTab({url:'/pages/verify/index'})}function records(){uni.switchTab({url:'/pages/records/index'})}</script>
<style scoped>.head{background:linear-gradient(135deg,#173d4f,#168f86);color:#fff;border-radius:32rpx;padding:38rpx;box-shadow:0 16rpx 32rpx #168f8630}.eyebrow{font-size:20rpx;letter-spacing:3rpx;opacity:.72}.head-row{display:flex;justify-content:space-between;align-items:center;margin-top:18rpx}.name{font-size:38rpx;font-weight:750}.status{background:#fff2;padding:10rpx 17rpx;border-radius:20rpx;font-size:24rpx}.dot{display:inline-block;width:10rpx;height:10rpx;border-radius:50%;background:#aef3c8;margin-right:8rpx}.stats{display:flex;margin-top:24rpx;padding:32rpx 0}.stats>view:not(.divider){flex:1;text-align:center;display:flex;flex-direction:column;gap:9rpx;color:#8894a6;font-size:24rpx}.divider{width:1rpx;background:#edf0f4;margin:6rpx 0}.num{font-size:40rpx;color:#203148;font-weight:750}.section-title{font-size:32rpx;font-weight:750;margin:38rpx 4rpx 20rpx}.actions{display:flex;gap:18rpx}.action{flex:1;padding:34rpx 10rpx;text-align:center;display:flex;flex-direction:column;gap:10rpx;color:#405069;font-size:27rpx;font-weight:600}.icon{font-size:52rpx;color:#168f86}.note{font-size:22rpx;color:#9aa6b7;font-weight:400}</style>
